<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import AppButton from '../../ui/components/AppButton.vue';
import type { SourceImportPreview } from './source-import';
import { sourceCapabilities } from './source-import';
export default defineComponent({name:'SourceImportDialog',components:{AppButton},props:{items:{type:Array as PropType<SourceImportPreview[]>,required:true},fileName:{type:String,default:''},busy:Boolean,error:{type:String,default:''}},emits:['update:items','confirm','close'],computed:{selectedCount():number{return this.items.filter(item=>item.selected).length},allSelected():boolean{return this.items.length>0&&this.selectedCount===this.items.length}},methods:{toggleAll(){this.$emit('update:items',this.items.map(item=>({...item,selected:!this.allSelected})))},toggle(index:number){this.$emit('update:items',this.items.map((item,itemIndex)=>itemIndex===index?{...item,selected:!item.selected}:item))},capabilities(item:SourceImportPreview){return sourceCapabilities(item.source)}}});
</script>
<template><div class="overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section class="dialog" role="dialog" aria-modal="true" :aria-label="$t('sources.import.title')"><header><div><p class="eyebrow">{{ $t('sources.import.eyebrow') }}</p><h2>{{ $t('sources.import.title') }}</h2><p>{{ fileName }} · {{ $t('sources.import.found',{count:items.length}) }}</p></div><AppButton variant="quiet" :disabled="busy" @click="$emit('close')">{{ $t('sources.close') }}</AppButton></header><div class="selection"><label><input type="checkbox" :checked="allSelected" :indeterminate="selectedCount>0&&!allSelected" :disabled="busy" @change="toggleAll"><span>{{ $t('sources.import.selectAll') }}</span></label><strong>{{ $t('sources.import.selected',{count:selectedCount}) }}</strong></div><ul><li v-for="(item,index) in items" :key="item.key"><label><input type="checkbox" :checked="item.selected" :disabled="busy" @change="toggle(index)"><span class="identity"><strong>{{ item.source.bookSourceName }}</strong><small>{{ item.source.bookSourceUrl }}</small><span class="badges"><em v-for="capability in capabilities(item)" :key="capability">{{ $t(`sources.capabilities.${capability}`) }}</em></span></span></label></li></ul><p v-if="error" class="error" role="alert">{{ error }}</p><footer><AppButton variant="secondary" :disabled="busy" @click="$emit('close')">{{ $t('sources.cancel') }}</AppButton><AppButton :busy="busy" :disabled="selectedCount===0" @click="$emit('confirm')">{{ $t('sources.import.confirm',{count:selectedCount}) }}</AppButton></footer></section></div></template>
<style scoped>.overlay{position:fixed;z-index:90;inset:0;display:flex;align-items:center;justify-content:center;padding:1rem;background:rgb(0 0 0/.42)}.dialog{width:min(46rem,100%);max-height:min(48rem,92dvh);display:grid;grid-template-rows:auto auto minmax(0,1fr) auto auto;gap:.8rem;padding:1rem;border-radius:var(--radius-lg);background:var(--color-paper-raised);color:var(--color-ink)}header,.selection,footer{display:flex;justify-content:space-between;align-items:center;gap:1rem}h2,p{margin:0}h2{font:700 1.25rem var(--font-literary)}header p{color:var(--color-ink-muted)}.eyebrow{color:var(--color-warm)!important;font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.selection{padding:.65rem;border-radius:var(--radius-md);background:var(--color-paper-muted)}.selection label,li label{display:flex;align-items:center;gap:.75rem}.selection input,li input{width:1.25rem;height:1.25rem;flex:0 0 auto}ul{list-style:none;overflow:auto;display:grid;gap:.45rem;margin:0;padding:0}li{padding:.7rem;border:1px solid var(--color-border);border-radius:var(--radius-md)}.identity{min-width:0;display:grid;gap:.15rem}.identity strong,.identity small{overflow-wrap:anywhere}.identity small{color:var(--color-ink-muted)}.badges{display:flex;flex-wrap:wrap;gap:.25rem;margin-top:.2rem}.badges em{border-radius:999px;padding:.18rem .42rem;background:var(--color-accent-soft);color:var(--color-accent-strong);font-size:.68rem;font-style:normal}.error{color:var(--color-danger)}footer{justify-content:flex-end}@media(max-width:34rem){.overlay{padding:0;align-items:flex-end}.dialog{max-height:92dvh;border-radius:var(--radius-lg) var(--radius-lg) 0 0}.selection{align-items:flex-start;flex-direction:column}}</style>